import crypto from "node:crypto";

export function signedHeaders(secret, clientId, method, pathname, rawBody = "") {
  const timestamp = String(Date.now()); // 毫秒
  const nonce = crypto.randomUUID();
  const digest = crypto.createHash("sha256").update(rawBody, "utf8").digest("hex");
  const canonical = [method.toUpperCase(), pathname, timestamp, nonce, digest].join("\n");
  return {
    "Content-Type": "application/json",
    "X-Client-Id": clientId,
    "X-Timestamp": timestamp,
    "X-Nonce": nonce,
    "X-Signature": crypto.createHmac("sha256", secret).update(canonical).digest("hex")
  };
}

// 后端示例；凭据来自环境变量，页面不保存密钥
import { signedHeaders } from "./sign.mjs";
const base = process.env.PHONE_CLOUD_BASE_URL;
const clientId = process.env.PHONE_CLOUD_CLIENT_ID;
const secret = process.env.PHONE_CLOUD_SECRET;
async function call(method, path, input, idempotencyKey) {
  const body = method === "GET" ? "" : JSON.stringify(input ?? {});
  const headers = signedHeaders(secret, clientId, method, path, body);
  if (idempotencyKey) headers["Idempotency-Key"] = idempotencyKey;
  const res = await fetch(new URL(path, base), {
    method, headers, ...(body ? { body } : {}),
    signal: AbortSignal.timeout(20000)
  });
  const data = await res.json();
  if (!res.ok) throw Object.assign(new Error(data.error), { status: res.status, data });
  return data;
}
